#include<bits/stdc++.h>
using namespace std;
const int N = 55;
int w[N][N];
int n,m;
bool check(int xa,int ya,int xb,int yb){
    int a[2]={0,0};
    for(int i = xa;i<=xb;i++){
        for(int j=ya;j<=yb;j++){
            a[w[i][j]]++;
        }
    }

    return a[0]==a[1];
}
int main(){
    cin>>n>>m;
    for(int i=1;i<=n;i++){
        string s;
        cin>>s;
        for(int j=1;j<=m;j++){
            w[i][j]=s[j-1]-'0';
        }
    }
    int ans = 0;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            for(int ii=i;ii<=n;ii++){
                for(int jj=j;jj<=m;jj++){
                    if(check(i,j,ii,jj)){
                        ans = max(ans,(ii-i+1)*(jj-j+1));
                    }
                }
            }
        }
    }
    cout<<ans<<"\n";
}

#include<bits/stdc++.h>
using namespace std;
const int N = 1010;
int a[N];
int n,k;
int main(){
    cin>>n>>k;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    sort(a+1,a+n+1);
    int ans=0;
    for(int i=1;i<=n;i++){
        int sum=0;
        for(int j=i;j>=1;j--){
            if(a[i]-a[j]<=k){
                sum+=a[j];
            }else break;
        }
        ans=max(ans,sum);
    }
    cout<<ans<<"\n";
}
